import"./chunk-VC46IEJQ.js";var e=(i,h,t,r,l,d,n,s,o,a)=>({name:{en:i,zh:h},desc:{en:t[0],zh:t[1]},tour:{en:r[0],zh:r[1]},...a?{spoiler:{en:a[0],zh:a[1]}}:{},source:{confidence:l,refs:d,book:{en:n[0],zh:n[1]},unknown:{en:s[0],zh:s[1]},interpretation:{en:o[0],zh:o[1]}}}),c={id:"qarth",intro:{en:"Qarth, the great trading city on the straits to the Jade Sea, stands behind three walls, each of a different stone and carved with a different theme. Within are the Pureborn, the warlocks and the merchant princes. The city plan here is an artistic reconstruction.",zh:"\u9B41\u5C14\u65AF\u662F\u627C\u5B88\u901A\u5F80\u7389\u6D77\u6D77\u5CE1\u7684\u8D38\u6613\u5927\u57CE\uFF0C\u57CE\u5916\u73AF\u7ED5\u4E09\u91CD\u57CE\u5899\uFF0C\u6BCF\u9053\u5899\u77F3\u6750\u4E0D\u540C\uFF0C\u96D5\u523B\u7684\u4E3B\u9898\u4E5F\u4E0D\u540C\u3002\u57CE\u4E2D\u6709\u7EAF\u8840\u8005\u3001\u672F\u58EB\u4E0E\u5546\u4E1A\u4EB2\u738B\u3002\u672C\u573A\u666F\u7684\u57CE\u5E02\u5E03\u5C40\u4E3A\u827A\u672F\u91CD\u6784\u3002"},notes:{en:"From the books: three walls (red sandstone carved with animals, grey granite with war, black marble with lovemaking), the Pureborn and their Hall of a Thousand Thrones, the Temple of Memory, Warlock's Way and its windowless houses, the House of the Undying (long, low, windowless, entered through a face), the merchant princes such as Xaro, the Garden of Gehane and the harbour bazaar. Invented here: street plan, positions, wall heights (exaggerated), tower shapes, gates, bazaar and garden layouts. The tall House of the Undying seen on television is deliberately not used.",zh:"\u4E66\u4E2D\u53EF\u636E\uFF1A\u4E09\u91CD\u57CE\u5899\uFF08\u7EA2\u7802\u5CA9\u523B\u8D70\u517D\u3001\u7070\u82B1\u5C97\u5CA9\u523B\u6218\u4E89\u3001\u9ED1\u5927\u7406\u77F3\u523B\u6B22\u7231\uFF09\u3001\u7EAF\u8840\u8005\u53CA\u5176\u5343\u5EA7\u4E4B\u5385\u3001\u8BB0\u5FC6\u795E\u6BBF\u3001\u672F\u58EB\u4E4B\u8DEF\u53CA\u5176\u65E0\u7A97\u623F\u5C4B\u3001\u4E0D\u673D\u8005\u4E4B\u6BBF\uFF08\u4F4E\u77EE\u7EF5\u957F\u3001\u65E0\u7A97\u3001\u4EE5\u4EBA\u8138\u4E3A\u95E8\uFF09\u3001\u590F\u7F57\u7B49\u5546\u4E1A\u4EB2\u738B\u3001\u76D6\u54C8\u5185\u82B1\u56ED\uFF0C\u4EE5\u53CA\u6E2F\u53E3\u96C6\u5E02\u3002\u672C\u573A\u666F\u81EA\u62DF\uFF1A\u8857\u9053\u5E03\u5C40\u3001\u5404\u5904\u4F4D\u7F6E\u3001\u57CE\u5899\u9AD8\u5EA6\uFF08\u6709\u6240\u5938\u5927\uFF09\u3001\u5854\u697C\u9020\u578B\u3001\u57CE\u95E8\uFF0C\u4EE5\u53CA\u96C6\u5E02\u4E0E\u82B1\u56ED\u7684\u5E03\u5C40\u3002\u7535\u89C6\u5267\u4E2D\u9AD8\u8038\u7684\u4E0D\u673D\u8005\u4E4B\u6BBF\u523B\u610F\u672A\u4E88\u91C7\u7528\u3002"},tour:["harbour","bazaar","triple-walls","gate-of-pillars","merchant-towers","xaro-palace","temple-of-memory","hall-of-a-thousand-thrones","pureborn-towers","warlocks-way","house-of-the-undying","gardens-of-gehane"],sources:[{ref:"acok",checked:"memory",note:{en:"Daenerys's chapters in Qarth (A Clash of Kings) supply nearly everything; recalled, not re-read.",zh:"\u51E0\u4E4E\u5168\u90E8\u5185\u5BB9\u51FA\u81EA\u300A\u5217\u738B\u7684\u7EB7\u4E89\u300B\u4E2D\u4E39\u59AE\u8389\u4E1D\u5728\u9B41\u5C14\u65AF\u7684\u7AE0\u8282\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u539F\u6587\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Search summaries of the wiki: wall materials, heights and carvings; the Hall of a Thousand Thrones; Warlock's Way and its windowless houses; the House of the Undying (grey, long, low, no towers or windows, black-barked trees, a face-shaped entrance); ghost grass reported in the Garden of Gehane; Xaro's gardens and pool. Pages could not be fetched.",zh:"\u7ECF\u7EF4\u57FA\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF1A\u57CE\u5899\u7684\u77F3\u6750\u3001\u9AD8\u5EA6\u4E0E\u96D5\u523B\uFF1B\u5343\u5EA7\u4E4B\u5385\uFF1B\u672F\u58EB\u4E4B\u8DEF\u53CA\u5176\u65E0\u7A97\u623F\u5C4B\uFF1B\u4E0D\u673D\u8005\u4E4B\u6BBF\uFF08\u7070\u77F3\u780C\u6210\u3001\u4F4E\u77EE\u7EF5\u957F\u3001\u65E0\u5854\u65E0\u7A97\u3001\u9ED1\u76AE\u6811\u73AF\u7ED5\u3001\u4EBA\u8138\u5F62\u5165\u53E3\uFF09\uFF1B\u76D6\u54C8\u5185\u82B1\u56ED\u957F\u51FA\u9B3C\u8349\u7684\u4F20\u95FB\uFF1B\u590F\u7F57\u5B85\u90B8\u7684\u82B1\u56ED\u4E0E\u6C34\u6C60\u3002\u9875\u9762\u672C\u8EAB\u65E0\u6CD5\u6253\u5F00\u3002"}},{ref:"twoiaf",checked:"not-accessed",note:{en:"Companion history of Qarth and the Pureborn was not consulted.",zh:"\u672A\u67E5\u9605\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\u4E2D\u9B41\u5C14\u65AF\u4E0E\u7EAF\u8840\u8005\u7684\u5386\u53F2\u3002"}}],landmarks:{"triple-walls":e("Triple Walls","\u4E09\u91CD\u57CE\u5899",["Three walls, one inside the other: red sandstone carved with beasts, grey granite carved with war, and black marble carved with lovers. Each is taller than the last.","\u4E09\u9053\u57CE\u5899\u5C42\u5C42\u76F8\u5957\uFF1A\u7EA2\u7802\u5CA9\u523B\u7740\u8D70\u517D\uFF0C\u7070\u82B1\u5C97\u5CA9\u523B\u7740\u6218\u4E89\uFF0C\u9ED1\u5927\u7406\u77F3\u523B\u7740\u6B22\u7231\uFF0C\u4E00\u9053\u9AD8\u8FC7\u4E00\u9053\u3002"],["Beasts, war, love: Qarth tells its story in three walls of three stones.","\u8D70\u517D\u3001\u6218\u4E89\u3001\u6B22\u7231\uFF1A\u9B41\u5C14\u65AF\u7528\u4E09\u79CD\u77F3\u5934\u3001\u4E09\u9053\u57CE\u5899\u8BB2\u8FF0\u81EA\u5DF1\u3002"],"high",["acok","awoiaf"],["Three walls of different stone and height (about 30, 40 and 50 feet) bearing the carvings described.","\u4E09\u9053\u57CE\u5899\u77F3\u6750\u4E0E\u9AD8\u5EA6\u5404\u5F02\uFF08\u7EA6\u4E09\u5341\u3001\u56DB\u5341\u3001\u4E94\u5341\u5C3A\uFF09\uFF0C\u96D5\u523B\u5982\u4E66\u4E2D\u6240\u8FF0\u3002"],["Their exact circuit, thickness and how they meet the sea.","\u786E\u5207\u8D70\u5411\u3001\u539A\u5EA6\uFF0C\u4EE5\u53CA\u57CE\u5899\u5982\u4F55\u4E0E\u6D77\u5CB8\u8854\u63A5\u3002"],["Heights are drawn about 1.8 times the stated figures; carvings are suggested by coloured relief panels.","\u9AD8\u5EA6\u7EA6\u4E3A\u4E66\u4E2D\u6570\u5B57\u7684\u4E00\u70B9\u516B\u500D\uFF1B\u96D5\u523B\u4EE5\u5F69\u8272\u6D6E\u96D5\u677F\u793A\u610F\u3002"]),"gate-of-pillars":e("Carved Gates","\u96D5\u82B1\u57CE\u95E8",["A monumental gateway framed by carved pillars in the outer wall, with matching gates in the inner walls.","\u5916\u5899\u4E0A\u4E00\u5EA7\u4EE5\u96D5\u82B1\u77F3\u67F1\u4E3A\u6846\u7684\u5B8F\u4F1F\u57CE\u95E8\uFF0C\u5185\u4E24\u9053\u5899\u4E5F\u6709\u76F8\u5E94\u7684\u95E8\u3002"],["Travellers from the Red Waste ride in between great carved pillars.","\u4ECE\u7EA2\u8272\u8352\u539F\u800C\u6765\u7684\u65C5\u4EBA\uFF0C\u8981\u4ECE\u5DE8\u5927\u7684\u96D5\u82B1\u77F3\u67F1\u4E4B\u95F4\u8FDB\u57CE\u3002"],"low",["acok"],["Daenerys rides in through the three walls; their gates are not described in detail.","\u4E39\u59AE\u8389\u4E1D\u7A7F\u8FC7\u4E09\u9053\u57CE\u5899\u5165\u57CE\uFF1B\u57CE\u95E8\u5E76\u65E0\u7EC6\u81F4\u63CF\u5199\u3002"],["The number, names and look of the gates.","\u57CE\u95E8\u7684\u6570\u91CF\u3001\u540D\u79F0\u4E0E\u6837\u8C8C\u3002"],["One north gate per wall, each with two thick carved pillars and a gilded lintel; the design is invented.","\u6BCF\u9053\u5899\u5728\u5317\u4FA7\u5404\u5F00\u4E00\u95E8\uFF0C\u5404\u6709\u4E24\u6839\u7C97\u5927\u7684\u96D5\u82B1\u77F3\u67F1\u4E0E\u9540\u91D1\u95E8\u6963\uFF1B\u5747\u4E3A\u81EA\u62DF\u3002"]),"hall-of-a-thousand-thrones":e("Hall of a Thousand Thrones","\u5343\u5EA7\u4E4B\u5385",["Where the Pureborn sit: a domed hall in which their ancestral carved thrones rise in tiers. A cutaway shows the interior.","\u7EAF\u8840\u8005\u8BAE\u4E8B\u4E4B\u6240\uFF1A\u7A79\u9876\u4E4B\u4E0B\uFF0C\u4ED6\u4EEC\u4E16\u4EE3\u76F8\u4F20\u7684\u96D5\u82B1\u5B9D\u5EA7\u5C42\u5C42\u5347\u8D77\u3002\u53EF\u6253\u5F00\u5256\u9762\u67E5\u770B\u5185\u90E8\u3002"],["The Pureborn hear petitions from the thrones of their ancestors, and refuse Daenerys.","\u7EAF\u8840\u8005\u5750\u5728\u7956\u5148\u4F20\u4E0B\u7684\u5B9D\u5EA7\u4E0A\u542C\u4EBA\u9648\u60C5\uFF0C\u4E5F\u62D2\u7EDD\u4E86\u4E39\u59AE\u8389\u4E1D\u3002"],"high",["acok","awoiaf"],["A marble-floored hall with tiers of carved thrones inlaid with amber, onyx, lapis and jade beneath a painted dome; an audience requires rites and bribes.","\u5927\u7406\u77F3\u5730\u9762\uFF0C\u9576\u5D4C\u7425\u73C0\u3001\u7F1F\u739B\u7459\u3001\u9752\u91D1\u77F3\u4E0E\u7FE1\u7FE0\u7684\u96D5\u82B1\u5B9D\u5EA7\u5C42\u5C42\u6392\u5217\uFF0C\u7A79\u9876\u7ED8\u6709\u58C1\u753B\uFF1B\u6C42\u89C1\u987B\u7ECF\u4EEA\u5F0F\u4E0E\u8D3F\u8D42\u3002"],["Its exterior, size and the exact number of thrones.","\u5916\u89C2\u3001\u89C4\u6A21\u4E0E\u5B9D\u5EA7\u7684\u786E\u5207\u6570\u91CF\u3002"],["A round marble drum under a blue dome; inside, a horseshoe of eight tiers.","\u5927\u7406\u77F3\u5706\u5F62\u6BBF\u8EAB\uFF0C\u4E0A\u8986\u84DD\u8272\u7A79\u9876\uFF1B\u5185\u90E8\u4E3A\u516B\u5C42\u9A6C\u8E44\u5F62\u5EA7\u5E2D\u3002"]),"pureborn-towers":e("Pureborn Towers","\u7EAF\u8840\u8005\u4E4B\u5854",["A cluster of tall, slender towers standing for the palaces of the Pureborn, Qarth's oldest families.","\u4E00\u7C07\u9AD8\u6311\u7EC6\u957F\u7684\u5854\u697C\uFF0C\u4EE3\u8868\u9B41\u5C14\u65AF\u6700\u53E4\u8001\u7684\u5BB6\u65CF\u2014\u2014\u7EAF\u8840\u8005\u7684\u5BAB\u90B8\u3002"],["The Pureborn descend from Qarth's ancient kings and command its Civic Guard.","\u7EAF\u8840\u8005\u662F\u9B41\u5C14\u65AF\u53E4\u4EE3\u541B\u738B\u7684\u540E\u88D4\uFF0C\u7EDF\u9886\u57CE\u5E02\u536B\u961F\u3002"],"low",["acok"],["The Pureborn are Qarth's old aristocracy; their dwellings are not described.","\u7EAF\u8840\u8005\u662F\u9B41\u5C14\u65AF\u7684\u53E4\u8001\u8D35\u65CF\uFF1B\u5176\u5C45\u6240\u5E76\u65E0\u63CF\u5199\u3002"],["Whether they live in towers at all, and what their palaces look like.","\u4ED6\u4EEC\u662F\u5426\u4F4F\u5728\u5854\u4E2D\uFF0C\u5BAB\u90B8\u53C8\u662F\u4F55\u6A21\u6837\u3002"],["Six colour-capped towers joined by a low palace; invented.","\u516D\u5EA7\u5F69\u9876\u9AD8\u5854\uFF0C\u4EE5\u4F4E\u77EE\u5BAB\u6BBF\u76F8\u8FDE\uFF1B\u4E3A\u81EA\u62DF\u3002"]),"house-of-the-undying":e("House of the Undying","\u4E0D\u673D\u8005\u4E4B\u6BBF",["A long, low, windowless palace of grey stone that coils like a serpent among black-barked trees; its door is set in a carved face.","\u4E00\u5EA7\u7070\u77F3\u780C\u6210\u3001\u4F4E\u77EE\u7EF5\u957F\u3001\u65E0\u7A97\u7684\u5BAB\u6BBF\uFF0C\u5982\u86C7\u822C\u76D8\u7ED5\u5728\u9ED1\u76AE\u6811\u6797\u95F4\uFF1B\u95E8\u5F00\u5728\u4E00\u5F20\u96D5\u523B\u7684\u4EBA\u8138\u4E0A\u3002"],["No towers, no windows: the warlocks' palace waits behind the mouth of a stone face.","\u65E0\u5854\uFF0C\u65E0\u7A97\uFF1A\u672F\u58EB\u7684\u5BAB\u6BBF\u85CF\u5728\u4E00\u5F20\u77F3\u8138\u7684\u53E3\u4E2D\u3002"],"high",["acok","awoiaf"],["A long, low, ancient building with no towers or windows, among black-barked trees whose leaves yield shade of the evening; the entrance is a tall oval shaped like a face.","\u4E00\u5EA7\u53E4\u8001\u3001\u4F4E\u77EE\u7EF5\u957F\u7684\u5EFA\u7B51\uFF0C\u65E0\u5854\u65E0\u7A97\uFF0C\u5468\u56F4\u662F\u9ED1\u76AE\u6811\uFF0C\u5176\u53F6\u53EF\u917F\u201C\u66AE\u5149\u4E4B\u5F71\u201D\uFF1B\u5165\u53E3\u662F\u4E00\u9053\u9AD8\u9AD8\u7684\u4EBA\u8138\u5F62\u692D\u5706\u95E8\u3002"],["Its interior layout and the extent of its grounds.","\u5185\u90E8\u5E03\u5C40\u4E0E\u5EAD\u9662\u8303\u56F4\u3002"],["A spiral of dark-roofed blocks ending at a stone face; the trees are drawn as dark cypresses.","\u6DF1\u8272\u5C4B\u9876\u7684\u5EFA\u7B51\u76D8\u6210\u87BA\u65CB\uFF0C\u5C3D\u5934\u662F\u4E00\u9762\u77F3\u96D5\u4EBA\u8138\uFF1B\u6797\u6728\u753B\u4F5C\u6DF1\u8272\u67CF\u6811\u3002"],["Daenerys's visit ends with Drogon setting the House of the Undying ablaze.","\u4E39\u59AE\u8389\u4E1D\u7684\u9020\u8BBF\u4EE5\u5353\u803F\u653E\u706B\u711A\u70E7\u4E0D\u673D\u8005\u4E4B\u6BBF\u544A\u7EC8\u3002"]),"warlocks-way":e("Warlock's Way","\u672F\u58EB\u4E4B\u8DEF",["A street of blank-walled, windowless houses.","\u4E00\u6761\u8857\uFF0C\u4E24\u65C1\u5C3D\u662F\u65E0\u7A97\u7684\u5149\u5899\u623F\u5C4B\u3002"],["No windows face the street; phantom tortoises are said to carry messages between the houses.","\u623F\u5C4B\u4E0D\u5411\u8857\u5F00\u7A97\uFF1B\u636E\u8BF4\u6709\u5E7D\u7075\u822C\u7684\u4E4C\u9F9F\u5728\u5C4B\u4E0E\u5C4B\u4E4B\u95F4\u4F20\u9012\u6D88\u606F\u3002"],"medium",["acok","awoiaf"],["A street of windowless houses; Xaro tells Daenerys of phantom tortoises carrying messages between them.","\u4E00\u6761\u6EE1\u662F\u65E0\u7A97\u623F\u5C4B\u7684\u8857\u9053\uFF1B\u590F\u7F57\u66FE\u5411\u4E39\u59AE\u8389\u4E1D\u8BB2\u8D77\u5E7D\u7075\u4E4C\u9F9F\u5728\u5176\u95F4\u4F20\u4FE1\u3002"],["Its length and position in the city.","\u957F\u5EA6\u4E0E\u5728\u57CE\u4E2D\u7684\u4F4D\u7F6E\u3002"],["Seven bluish plaster blocks in two staggered rows.","\u4E24\u5217\u9519\u843D\u7684\u84DD\u7070\u8272\u7070\u6CE5\u623F\u5C4B\uFF0C\u5171\u4E03\u5EA7\u3002"]),"temple-of-memory":e("Temple of Memory","\u8BB0\u5FC6\u795E\u6BBF",["The temple where a petitioner must make a sacrifice before seeking an audience with the Pureborn.","\u6C42\u89C1\u7EAF\u8840\u8005\u4E4B\u524D\uFF0C\u987B\u5148\u5728\u8FD9\u5EA7\u795E\u6BBF\u732E\u796D\u3002"],["Before any audience, a sacrifice is made here, one step in a long ritual.","\u8C12\u89C1\u4E4B\u524D\uFF0C\u5148\u5728\u6B64\u732E\u796D\uFF0C\u8FD9\u53EA\u662F\u7E41\u7410\u4EEA\u5F0F\u4E2D\u7684\u4E00\u6B65\u3002"],"medium",["acok"],["To be heard by the Pureborn one must sacrifice at the Temple of Memory, among other rites and bribes.","\u82E5\u60F3\u5F97\u5230\u7EAF\u8840\u8005\u63A5\u89C1\uFF0C\u987B\u5728\u8BB0\u5FC6\u795E\u6BBF\u732E\u796D\uFF0C\u8FD8\u8981\u884C\u5176\u4ED6\u4EEA\u5F0F\u3001\u9001\u4E0A\u8D3F\u8D42\u3002"],["Its form, size and rites.","\u5F62\u5236\u3001\u89C4\u6A21\u4E0E\u4EEA\u8F68\u3002"],["A white-marble colonnaded block with a red dome; invented.","\u767D\u5927\u7406\u77F3\u67F1\u5ECA\u5EFA\u7B51\uFF0C\u4E0A\u8986\u7EA2\u8272\u7A79\u9876\uFF1B\u4E3A\u81EA\u62DF\u3002"]),"xaro-palace":e("Xaro's Palace","\u590F\u7F57\u5B85\u90B8",["The lavish home of the merchant prince Xaro Xhoan Daxos, with gardens, a bathing pool and many rooms.","\u5546\u4E1A\u4EB2\u738B\u590F\u7F57\xB7\u8C6A\u5B89\xB7\u8FBE\u514B\u7D22\u65AF\u7684\u5962\u534E\u5B85\u90B8\uFF0C\u6709\u82B1\u56ED\u3001\u6D74\u6C60\u4E0E\u91CD\u91CD\u5385\u5BA4\u3002"],["A merchant prince's house is a palace: fountains, gardens and a host of servants.","\u5546\u4E1A\u4EB2\u738B\u7684\u5B85\u5B50\u582A\u6BD4\u5BAB\u6BBF\uFF1A\u55B7\u6CC9\u3001\u82B1\u56ED\u4E0E\u6210\u7FA4\u4EC6\u5F79\u3002"],"medium",["acok","awoiaf"],["Xaro, one of the Thirteen, hosts Daenerys in a palace with gardens of lavender and mint and a marble pool of golden fish.","\u5341\u4E09\u4EBA\u4E4B\u4E00\u7684\u590F\u7F57\u5728\u5B85\u90B8\u4E2D\u6B3E\u5F85\u4E39\u59AE\u8389\u4E1D\uFF0C\u90A3\u91CC\u6709\u85B0\u8863\u8349\u4E0E\u8584\u8377\u7684\u82B1\u56ED\uFF0C\u8FD8\u6709\u517B\u7740\u91D1\u9C7C\u7684\u5927\u7406\u77F3\u6C34\u6C60\u3002"],["Its position, plan and size.","\u4F4D\u7F6E\u3001\u5E73\u9762\u4E0E\u89C4\u6A21\u3002"],["A large plaster palace with two domes, ringed by guest houses.","\u4E00\u5EA7\u5E26\u4E24\u4E2A\u7A79\u9876\u7684\u5927\u578B\u7070\u6CE5\u5BAB\u90B8\uFF0C\u56DB\u5468\u73AF\u7ED5\u5BA2\u820D\u3002"]),"merchant-towers":e("Merchant Towers","\u5546\u4EBA\u9AD8\u5854",["Tall banded towers of the great trading houses, capped in tile and gold and flying pennants.","\u5927\u5546\u5BB6\u7684\u6761\u7EB9\u9AD8\u5854\uFF0C\u9876\u8986\u5F69\u74E6\u4E0E\u91D1\u9970\uFF0C\u5F69\u65D7\u98D8\u626C\u3002"],["Qarth's merchant guilds, such as the Thirteen and the Spicers, rival the Pureborn.","\u9B41\u5C14\u65AF\u7684\u5546\u4F1A\uFF0C\u5982\u5341\u4E09\u4EBA\u4E0E\u9999\u6599\u5546\u53E4\u4F1A\uFF0C\u8DB3\u4EE5\u4E0E\u7EAF\u8840\u8005\u5206\u5EAD\u6297\u793C\u3002"],"low",["acok"],["Qarth is ruled in practice by rich merchant guilds; their buildings are not described.","\u9B41\u5C14\u65AF\u5B9E\u9645\u4E0A\u7531\u5BCC\u6709\u7684\u5546\u4F1A\u638C\u63A7\uFF1B\u5176\u5EFA\u7B51\u672A\u89C1\u63CF\u5199\u3002"],["Whether merchants build towers, and which belong to whom.","\u5546\u4EBA\u662F\u5426\u5EFA\u5854\uFF0C\u54EA\u5EA7\u53C8\u5F52\u8C01\u6240\u6709\u3002"],["Seven banded towers in bright tile; invented.","\u4E03\u5EA7\u5F69\u74E6\u6761\u7EB9\u9AD8\u5854\uFF1B\u4E3A\u81EA\u62DF\u3002"]),bazaar:e("Bazaar","\u96C6\u5E02",["Stalls under striped awnings by the harbour, where goods from across the known world change hands.","\u6E2F\u53E3\u65C1\u6761\u7EB9\u906E\u7BF7\u4E0B\u7684\u644A\u4F4D\uFF0C\u5DF2\u77E5\u4E16\u754C\u5404\u5730\u7684\u8D27\u7269\u5728\u6B64\u6613\u624B\u3002"],["Silks, spices and curiosities change hands here, and danger can hide in any stall.","\u4E1D\u7EF8\u3001\u9999\u6599\u4E0E\u5947\u73CD\u5728\u8FD9\u91CC\u4E70\u5356\uFF0C\u5371\u9669\u4E5F\u53EF\u80FD\u85CF\u5728\u4EFB\u4F55\u4E00\u4E2A\u644A\u4F4D\u91CC\u3002"],"medium",["acok"],["Daenerys walks the harbour market looking for ships and goods.","\u4E39\u59AE\u8389\u4E1D\u66FE\u5728\u6E2F\u53E3\u96C6\u5E02\u4E2D\u5BFB\u627E\u8239\u53EA\u4E0E\u8D27\u7269\u3002"],["Market names and layout.","\u96C6\u5E02\u540D\u79F0\u4E0E\u5E03\u5C40\u3002"],["A grid of awning-roofed stalls on the east side.","\u4E1C\u4FA7\u68CB\u76D8\u5F0F\u6392\u5217\u7684\u906E\u7BF7\u644A\u4F4D\u3002"]),"gardens-of-gehane":e("Garden of Gehane","\u76D6\u54C8\u5185\u82B1\u56ED",["A walled garden of palms and a still pond, drawn as a green pocket among the dusty streets.","\u4E00\u5EA7\u6709\u56F4\u5899\u7684\u82B1\u56ED\uFF0C\u68D5\u6988\u73AF\u7ED5\uFF0C\u4E00\u6C60\u9759\u6C34\uFF0C\u753B\u4F5C\u5C18\u571F\u8857\u5DF7\u4E2D\u7684\u4E00\u7247\u7EFF\u610F\u3002"],["A green pocket in a city of stone, where strange things have begun to grow.","\u77F3\u57CE\u4E2D\u7684\u4E00\u65B9\u7EFF\u610F\uFF0C\u8FD1\u6765\u5374\u957F\u51FA\u4E86\u5947\u5F02\u4E4B\u7269\u3002"],"low",["acok","awoiaf"],["Named only once: Xaro reports that ghost grass is growing in the Garden of Gehane.","\u4E66\u4E2D\u4EC5\u63D0\u53CA\u4E00\u6B21\uFF1A\u590F\u7F57\u8BF4\u76D6\u54C8\u5185\u82B1\u56ED\u91CC\u957F\u51FA\u4E86\u9B3C\u8349\u3002"],["What it actually is, who Gehane was, and where it lies.","\u5B83\u7A76\u7ADF\u662F\u4EC0\u4E48\u3001\u76D6\u54C8\u5185\u662F\u8C01\uFF0C\u4EE5\u53CA\u4F4D\u4E8E\u4F55\u5904\u3002"],["Palms, oaks and a round pond in the west; entirely invented.","\u897F\u4FA7\u7684\u68D5\u6988\u3001\u6A61\u6811\u4E0E\u5706\u6C60\uFF1B\u5B8C\u5168\u4E3A\u81EA\u62DF\u3002"]),harbour:e("Harbour","\u6E2F\u53E3",["A great port where galleys, cogs and dhows crowd stone quays beneath the walls.","\u4E00\u5EA7\u5927\u6E2F\uFF0C\u6868\u5E06\u8239\u3001\u67EF\u514B\u8239\u4E0E\u4E09\u89D2\u5E06\u8239\u6324\u6EE1\u57CE\u5899\u4E0B\u7684\u77F3\u780C\u7801\u5934\u3002"],["Sea trade built these walls. Daenerys came here looking for ships.","\u6D77\u4E0A\u8D38\u6613\u7B51\u8D77\u4E86\u8FD9\u4E9B\u57CE\u5899\u3002\u4E39\u59AE\u8389\u4E1D\u66FE\u6765\u6B64\u5BFB\u627E\u8239\u53EA\u3002"],"high",["acok"],["Qarth is a great port where traders of east and west meet; Daenerys seeks ships there.","\u9B41\u5C14\u65AF\u662F\u4E1C\u897F\u65B9\u5546\u4EBA\u6C47\u805A\u7684\u5927\u6E2F\uFF1B\u4E39\u59AE\u8389\u4E1D\u66FE\u5728\u6B64\u5BFB\u8239\u3002"],["Harbour layout and the number of quays.","\u6E2F\u53E3\u5E03\u5C40\u4E0E\u7801\u5934\u6570\u91CF\u3002"],["A straight quay with piers and eight sample ships.","\u4E00\u9053\u7B14\u76F4\u7801\u5934\uFF0C\u914D\u4EE5\u6808\u6865\u4E0E\u516B\u8258\u793A\u610F\u8239\u53EA\u3002"])}};export{c as default};
